import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.C8R-a4p3.js";import"./chunks/assets.B69s6tm2.js";var i=JSON.parse(`{"title":"Hermes Agent — My Own Infrastructure","description":"Hermes Agent: self-hosted AI brain (hermes-stack) that routes models, runs automations and keeps my agent fleet supplied.","frontmatter":{"title":"Hermes Agent — My Own Infrastructure","description":"Hermes Agent: self-hosted AI brain (hermes-stack) that routes models, runs automations and keeps my agent fleet supplied."},"headers":[],"relativePath":"en/agentic/hermes/index.md","filePath":"en/agentic/hermes/index.md"}`),a={name:`en/agentic/hermes/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="hermes-agent-—-my-own-infrastructure" tabindex="-1">Hermes Agent — My Own Infrastructure <a class="header-anchor" href="#hermes-agent-—-my-own-infrastructure" aria-label="Permalink to “Hermes Agent — My Own Infrastructure”">​</a></h1><p><strong>Hermes Agent</strong> is the piece I built myself: the coordinator layer of my entire agentic setup, shipped as <a href="https://github.com/Godde3s/hermes-stack" target="_blank" rel="noreferrer">hermes-stack</a> on a free Hugging Face Space. Where the other tools are individuals, Hermes is the <em>manager</em> — it routes models, holds context, runs automations, and keeps every other agent supplied with the right brain at the right time.</p><h2 id="what-hermes-actually-does-all-day" tabindex="-1">What Hermes actually does all day <a class="header-anchor" href="#what-hermes-actually-does-all-day" aria-label="Permalink to “What Hermes actually does all day”">​</a></h2><ul><li><strong>Model routing.</strong> Every request from every tool can flow through my <a href="/Usf/en/projects/omnirouter/">OmniRouter</a> — cheap models for grunt work, premium ones for judgment calls.</li><li><strong>Automation brain.</strong> Webhook-triggered tasks: watch a repo, ping me on Telegram when a deploy breaks, summarize overnight CI logs.</li><li><strong>Context keeper.</strong> Long-running projects keep their briefs, decisions and state with Hermes, not scattered across terminal scrolls.</li><li><strong>Roaming endpoint.</strong> Any OpenAI-compatible client can talk to it — my phone&#39;s app, a cron job, another agent.</li></ul><h2 id="why-self-host-it" tabindex="-1">Why self-host it? <a class="header-anchor" href="#why-self-host-it" aria-label="Permalink to “Why self-host it?”">​</a></h2><p>Because dependence is a design decision. A hosted &quot;AI assistant&quot; can change pricing, rate-limit me, or vanish — and in my region, it can also be blocked outright. Hermes Stack runs on infrastructure I control, behind routers I control, with fallbacks I configured. When a provider dies, nothing in my workflow changes; the router simply stops asking.</p><figure class="concept-illustration"><img src="/Usf/assets/img/agentic-loop.svg" alt="Hermes coordinating OpenCode, Codex and Claude Code" loading="lazy"><figcaption>One brain, three specialists, zero vendor lock-in.</figcaption></figure><div class="tip custom-block"><p class="custom-block-title">Deploy your own</p><p>The whole stack is one click from the repo: <a href="https://github.com/Godde3s/hermes-stack" target="_blank" rel="noreferrer">github.com/Godde3s/hermes-stack</a> — free tier friendly, documented, mine to improve in public.</p></div>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};